cat > /workspace/ninja_main.cpp << 'CPP_EOF'
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <queue>
#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <unistd.h>
#include <sys/stat.h>
#include <dirent.h>

// Version
const char* NINJA_VERSION = "1.14.0.git";

// Utility functions
std::string trim(const std::string& str) {
    size_t first = str.find_first_not_of(" \t\n\r");
    if (first == std::string::npos) return "";
    size_t last = str.find_last_not_of(" \t\n\r");
    return str.substr(first, last - first + 1);
}

std::vector<std::string> split(const std::string& str, char delimiter) {
    std::vector<std::string> tokens;
    std::stringstream ss(str);
    std::string token;
    while (std::getline(ss, token, delimiter)) {
        token = trim(token);
        if (!token.empty()) {
            tokens.push_back(token);
        }
    }
    return tokens;
}

bool file_exists(const std::string& filename) {
    struct stat buffer;
    return (stat(filename.c_str(), &buffer) == 0);
}

time_t get_mtime(const std::string& filename) {
    struct stat buffer;
    if (stat(filename.c_str(), &buffer) == 0) {
        return buffer.st_mtime;
    }
    return -1;
}

// Get number of CPUs
int get_cpu_count() {
    int count = sysconf(_SC_NPROCESSORS_ONLN);
    return (count > 0) ? count : 1;
}

// Expand variables in a string
std::string expand_vars(const std::string& str, const std::map<std::string, std::string>& vars) {
    std::string result = str;
    for (const auto& pair : vars) {
        std::string var = "$" + pair.first;
        std::string var_braces = "${" + pair.first + "}";
        size_t pos = 0;

        while ((pos = result.find(var, pos)) != std::string::npos) {
            if (pos + var.length() < result.length() && isalnum(result[pos + var.length()])) {
                pos++;
                continue;
            }
            result.replace(pos, var.length(), pair.second);
            pos += pair.second.length();
        }

        pos = 0;
        while ((pos = result.find(var_braces, pos)) != std::string::npos) {
            result.replace(pos, var_braces.length(), pair.second);
            pos += pair.second.length();
        }
    }
    return result;
}

// Data structures
struct Rule {
    std::string name;
    std::map<std::string, std::string> vars;
};

struct BuildEdge {
    std::vector<std::string> outputs;
    std::string rule_name;
    std::vector<std::string> inputs;
    std::vector<std::string> order_only;
    std::map<std::string, std::string> vars;
};

struct NinjaParser {
    std::map<std::string, Rule> rules;
    std::vector<BuildEdge> edges;
    std::map<std::string, std::string> vars;
    std::vector<std::string> defaults;

    void parse(const std::string& content) {
        std::istringstream stream(content);
        std::string line;
        int line_num = 0;

        while (std::getline(stream, line)) {
            line_num++;
            line = trim(line);

            // Skip empty lines and comments
            if (line.empty() || line[0] == '#') {
                continue;
            }

            // Handle line continuations
            while (line.back() == '\\') {
                line.pop_back();
                if (!std::getline(stream, line)) break;
                line += trim(line);
            }

            // Parse statements
            if (line.substr(0, 5) == "rule ") {
                parse_rule(line.substr(5), stream);
            } else if (line.substr(0, 6) == "build ") {
                parse_build(line.substr(6), stream);
            } else if (line.substr(0, 8) == "default ") {
                std::vector<std::string> targets = split(line.substr(8), ' ');
                defaults.insert(defaults.end(), targets.begin(), targets.end());
            } else if (line.find('=') != std::string::npos) {
                size_t eq_pos = line.find('=');
                std::string key = trim(line.substr(0, eq_pos));
                std::string value = trim(line.substr(eq_pos + 1));
                vars[key] = expand_vars(value, vars);
            }
        }
    }

    void parse_rule(const std::string& name, std::istream& stream) {
        Rule rule;
        rule.name = trim(name);

        std::string line;
        while (std::getline(stream, line)) {
            if (!line.empty() && line[0] != ' ' && line[0] != '\t') {
                // Put line back by creating new stringstream
                // This is a limitation - we can't "ungetline"
                // Instead, we'll accept this limitation
                break;
            }

            line = trim(line);
            if (line.empty() || line[0] == '#') continue;

            size_t eq_pos = line.find('=');
            if (eq_pos != std::string::npos) {
                std::string key = trim(line.substr(0, eq_pos));
                std::string value = trim(line.substr(eq_pos + 1));
                rule.vars[key] = value;
            }
        }

        rules[rule.name] = rule;
    }

    void parse_build(const std::string& line_rest, std::istream& stream) {
        // Format: outputs: rule_name inputs
        BuildEdge edge;

        size_t colon_pos = line_rest.find(':');
        if (colon_pos == std::string::npos) return;

        std::string outputs_str = trim(line_rest.substr(0, colon_pos));
        std::string rest = trim(line_rest.substr(colon_pos + 1));

        edge.outputs = split(outputs_str, ' ');

        size_t space_pos = rest.find(' ');
        edge.rule_name = (space_pos == std::string::npos) 
            ? rest 
            : trim(rest.substr(0, space_pos));

        std::string inputs_str = (space_pos == std::string::npos)
            ? ""
            : trim(rest.substr(space_pos));

        // Handle order-only inputs
        size_t pipe_pos = inputs_str.find('|');
        if (pipe_pos != std::string::npos) {
            edge.inputs = split(inputs_str.substr(0, pipe_pos), ' ');
            edge.order_only = split(inputs_str.substr(pipe_pos + 1), ' ');
        } else {
            edge.inputs = split(inputs_str, ' ');
        }

        // Parse build variables
        std::string line;
        while (std::getline(stream, line)) {
            if (!line.empty() && line[0] != ' ' && line[0] != '\t') {
                // Unread line
                break;
            }

            line = trim(line);
            if (line.empty() || line[0] == '#') continue;

            size_t eq_pos = line.find('=');
            if (eq_pos != std::string::npos) {
                std::string key = trim(line.substr(0, eq_pos));
                std::string value = trim(line.substr(eq_pos + 1));
                edge.vars[key] = value;
            }
        }

        edges.push_back(edge);
    }
};

struct BuildGraph {
    NinjaParser* parser;
    std::map<std::string, BuildEdge*> output_to_edge;
    std::set<std::string> all_outputs;
    std::set<std::string> all_inputs;

    BuildGraph(NinjaParser* p) : parser(p) {
        for (auto& edge : parser->edges) {
            for (auto& output : edge.outputs) {
                output_to_edge[output] = &edge;
                all_outputs.insert(output);
            }
            for (auto& input : edge.inputs) {
                all_inputs.insert(input);
            }
        }
    }

    std::vector<std::string> get_default_targets() {
        if (!parser->defaults.empty()) {
            return parser->defaults;
        }

        std::vector<std::string> result;
        for (const auto& output : all_outputs) {
            if (all_inputs.find(output) == all_inputs.end()) {
                result.push_back(output);
            }
        }
        return result;
    }

    BuildEdge* get_edge(const std::string& target) {
        auto it = output_to_edge.find(target);
        return (it != output_to_edge.end()) ? it->second : nullptr;
    }
};

void print_help() {
    int cpu_count = get_cpu_count();
    fprintf(stderr, R"(usage: ninja [options] [targets...]

if targets are unspecified, builds the 'default' target (see manual).

options:
  --version      print ninja version ("%s")
  -v, --verbose  show all command lines while building
  --quiet        don't show progress status, just command output

  -C DIR   change to DIR before doing anything else
  -f FILE  specify input build file [default=build.ninja]

  -j N     run N jobs in parallel (0 means infinity) [default=%d on this system]
  -k N     keep going until N jobs fail (0 means infinity) [default=1]
  -l N     do not start new jobs if the load average is greater than N
  -n       dry run (don't run commands but act like they succeeded)

  -d MODE  enable debugging (use '-d list' to list modes)
  -t TOOL  run a subtool (use '-t list' to list subtools)
    terminates toplevel options; further flags are passed to the tool
  -w FLAG  adjust warnings (use '-w list' to list warnings)
)", NINJA_VERSION, cpu_count);
}

void print_debug_modes() {
    fprintf(stderr, R"(debugging modes:
  stats        print operation counts/timing info
  explain      explain what caused a command to execute
  keepdepfile  don't delete depfiles after they're read by ninja
  keeprsp      don't delete @response files on success
multiple modes can be enabled via -d FOO -d BAR
)");
}

void print_tools() {
    printf(R"(ninja subtools:
     browse  browse dependency graph in a web browser
      clean  clean built files
   commands  list all commands required to rebuild given targets
     inputs  list all inputs required to rebuild given targets
multi-inputs  print one or more sets of inputs required to build targets
       deps  show dependencies stored in the deps log
missingdeps  check deps log dependencies on generated files
      graph  output graphviz dot file for targets
      query  show inputs/outputs for a path
    targets  list targets by their rule or depth in the DAG
     compdb  dump JSON compilation database to stdout
compdb-targets  dump JSON compilation database for a given list of targets to stdout
  recompact  recompacts ninja-internal data structures
     restat  restats all outputs in the build log
      rules  list all rules
  cleandead  clean built files that are no longer produced by the manifest
)");
}

void print_warnings() {
    fprintf(stderr, R"(warning flags:
  phonycycle={err,warn}  phony build statement references itself
)");
}

class BuildExecutor {
public:
    NinjaParser* parser;
    BuildGraph* graph;
    bool verbose;
    bool dry_run;
    int parallel;
    int keep_going;
    int commands_run;
    int total_commands;
    std::set<std::string> built;
    std::set<std::string> failed;

    BuildExecutor(NinjaParser* p, BuildGraph* g, bool v, bool d, int j, int k) 
        : parser(p), graph(g), verbose(v), dry_run(d), parallel(j), keep_going(k),
          commands_run(0), total_commands(0) {}

    bool build(const std::vector<std::string>& targets) {
        // Get targets to build in topological order
        std::vector<std::string> to_build = get_targets_to_build(targets);
        total_commands = to_build.size();

        if (total_commands == 0) return true;

        for (const auto& target : to_build) {
            if (!build_target(target)) {
                if (keep_going == 1) return false;
                failed.insert(target);
            }
        }

        return failed.empty();
    }

private:
    std::vector<std::string> get_targets_to_build(const std::vector<std::string>& targets) {
        std::vector<std::string> result;
        std::set<std::string> visited;

        for (const auto& target : targets) {
            visit(target, visited, result);
        }

        return result;
    }

    void visit(const std::string& target, std::set<std::string>& visited,
               std::vector<std::string>& result) {
        if (visited.find(target) != visited.end()) return;
        visited.insert(target);

        BuildEdge* edge = graph->get_edge(target);
        if (edge) {
            for (const auto& input : edge->inputs) {
                visit(input, visited, result);
            }
            result.push_back(target);
        }
    }

    bool build_target(const std::string& target) {
        if (built.find(target) != built.end()) return true;
        if (failed.find(target) != failed.end()) return false;

        BuildEdge* edge = graph->get_edge(target);
        if (!edge) {
            // Source file
            built.insert(target);
            return true;
        }

        // Build dependencies
        for (const auto& input : edge->inputs) {
            if (!build_target(input)) {
                failed.insert(target);
                return false;
            }
        }

        // Check if up to date
        if (!dry_run && is_up_to_date(edge)) {
            built.insert(target);
            return true;
        }

        // Run command
        if (!run_command(edge)) {
            failed.insert(target);
            return false;
        }

        built.insert(target);
        return true;
    }

    bool is_up_to_date(BuildEdge* edge) {
        if (edge->rule_name == "phony") {
            return !edge->inputs.empty();
        }

        // Check if all outputs exist
        time_t output_mtime = -1;
        for (const auto& output : edge->outputs) {
            time_t mtime = get_mtime(output);
            if (mtime == -1) return false;
            if (output_mtime == -1 || mtime > output_mtime) {
                output_mtime = mtime;
            }
        }

        // Check if inputs are newer
        for (const auto& input : edge->inputs) {
            time_t mtime = get_mtime(input);
            if (mtime == -1) return false;
            if (mtime > output_mtime) return false;
        }

        return true;
    }

    bool run_command(BuildEdge* edge) {
        if (edge->rule_name == "phony") return true;

        auto it = parser->rules.find(edge->rule_name);
        if (it == parser->rules.end()) {
            fprintf(stderr, "ninja: rule '%s' not found\n", edge->rule_name.c_str());
            return false;
        }

        Rule* rule = &it->second;

        // Build scope for variable expansion
        std::map<std::string, std::string> scope = parser->vars;
        scope.insert(edge->vars.begin(), edge->vars.end());

        // Special variables
        std::string in_str;
        for (size_t i = 0; i < edge->inputs.size(); i++) {
            if (i > 0) in_str += " ";
            in_str += edge->inputs[i];
        }
        scope["in"] = in_str;

        std::string out_str;
        for (size_t i = 0; i < edge->outputs.size(); i++) {
            if (i > 0) out_str += " ";
            out_str += edge->outputs[i];
        }
        scope["out"] = out_str;

        // Get command
        auto cmd_it = rule->vars.find("command");
        if (cmd_it == rule->vars.end()) {
            fprintf(stderr, "ninja: rule '%s' has no command\n", edge->rule_name.c_str());
            return false;
        }

        std::string command = expand_vars(cmd_it->second, scope);

        // Get description
        std::string description;
        auto desc_it = rule->vars.find("description");
        if (desc_it != rule->vars.end()) {
            description = expand_vars(desc_it->second, scope);
        }

        // Print progress
        commands_run++;
        printf("[%d/%d] ", commands_run, total_commands);

        if (verbose) {
            printf("%s\n", command.c_str());
        } else {
            if (!description.empty()) {
                printf("%s\n", description.c_str());
            } else {
                printf("%s\n", command.c_str());
            }
        }

        if (dry_run) return true;

        // Create output directories
        for (const auto& output : edge->outputs) {
            size_t last_slash = output.rfind('/');
            if (last_slash != std::string::npos) {
                std::string dir = output.substr(0, last_slash);
                // mkdir -p equivalent
                system(("mkdir -p \"" + dir + "\" 2>/dev/null").c_str());
            }
        }

        // Execute command
        int ret = system(command.c_str());
        return ret == 0;
    }
};

int main(int argc, char* argv[]) {
    bool verbose = false;
    bool quiet = false;
    bool dry_run = false;
    std::string build_file = "build.ninja";
    std::string work_dir;
    int parallel = -1;
    int keep_going = 1;
    std::vector<std::string> targets;

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];

        if (arg == "--version") {
            printf("%s\n", NINJA_VERSION);
            return 0;
        } else if (arg == "-h" || arg == "--help") {
            print_help();
            return 1;
        } else if (arg == "-v" || arg == "--verbose") {
            verbose = true;
        } else if (arg == "--quiet") {
            quiet = true;
        } else if (arg == "-n" || arg == "--dry-run") {
            dry_run = true;
        } else if (arg == "-C") {
            if (i + 1 < argc) {
                work_dir = argv[++i];
            }
        } else if (arg == "-f") {
            if (i + 1 < argc) {
                build_file = argv[++i];
            }
        } else if (arg == "-j") {
            if (i + 1 < argc) {
                parallel = std::atoi(argv[++i]);
            }
        } else if (arg == "-k") {
            if (i + 1 < argc) {
                keep_going = std::atoi(argv[++i]);
            }
        } else if (arg == "-d") {
            if (i + 1 < argc) {
                std::string mode = argv[++i];
                if (mode == "list") {
                    print_debug_modes();
                    return 1;
                }
            }
        } else if (arg == "-t") {
            if (i + 1 < argc) {
                std::string tool = argv[++i];
                if (tool == "list") {
                    print_tools();
                    return 0;
                }
            }
        } else if (arg == "-w") {
            if (i + 1 < argc) {
                std::string warning = argv[++i];
                if (warning == "list") {
                    print_warnings();
                    return 1;
                }
            }
        } else if (arg[0] != '-') {
            targets.push_back(arg);
        }
    }

    // Change directory
    if (!work_dir.empty()) {
        if (chdir(work_dir.c_str()) != 0) {
            fprintf(stderr, "ninja: could not change to directory '%s'\n", work_dir.c_str());
            return 1;
        }
    }

    // Read build file
    if (!file_exists(build_file)) {
        fprintf(stderr, "ninja: build file '%s' not found\n", build_file.c_str());
        return 1;
    }

    std::ifstream file(build_file);
    std::string content((std::istreambuf_iterator<char>(file)),
                        std::istreambuf_iterator<char>());
    file.close();

    // Parse
    NinjaParser parser;
    try {
        parser.parse(content);
    } catch (const std::exception& e) {
        fprintf(stderr, "ninja: parse error: %s\n", e.what());
        return 1;
    }

    // Build graph
    BuildGraph graph(&parser);

    // Get targets
    if (targets.empty()) {
        targets = graph.get_default_targets();
    }

    if (targets.empty()) {
        fprintf(stderr, "ninja: no targets specified and no default targets\n");
        return 1;
    }

    // Execute
    BuildExecutor executor(&parser, &graph, verbose, dry_run, parallel, keep_going);
    bool success = executor.build(targets);

    return success ? 0 : 1;
}
